INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b9977b40cd7afc61ddc81473948ffdd463d53ee9/content/books/zizhi-tongjian/vol-288/year-0948/part-03/sources/library/jiuwudaishi-107-yang-bin-power/source.txt", "note": "《旧五代史》卷一百〇七，段落 jiu-wudaishi-205deb4a7860-p002563；EPUB电子本，纸本及异文待核", "id": "53cb4f0b-1a28-539d-8d25-5a743f2bde5b"}, {"title": "宋史·卷262·李涛传·免相", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b9977b40cd7afc61ddc81473948ffdd463d53ee9/content/books/zizhi-tongjian/vol-288/year-0948/part-03/sources/library/songshi-262-li-tao-dismissal/source.txt", "note": "《宋史》卷262·李涛传·免相，段落 songshi-9c6e46fee832-p058123；已核上下文及传主，纸本及异文待核。", "id": "3513b31c-44f0-5466-abbd-541bc3f04d8c"}, {"title": "资治通鉴·后汉纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b9977b40cd7afc61ddc81473948ffdd463d53ee9/content/books/zizhi-tongjian/vol-288/year-0948/part-03/sources/library/tongjian-288-948-march-april-conflict/source.txt", "note": "《资治通鉴》后汉纪三，段落 zizhi-tongjian-a63549944a71-p003416；电子底本待考，分段待核", "id": "ae17a861-a3af-58c8-9670-c6a31156d334"}, {"title": "新五代史·卷五十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b9977b40cd7afc61ddc81473948ffdd463d53ee9/content/books/zizhi-tongjian/vol-288/year-0948/part-03/sources/library/xinwudaishi-052-li-shouzhen-revolt/source.txt", "note": "《新五代史》卷五十二，段落 xin-wudaishi-b08f244b9241-p002042；EPUB电子本，纸本及异文待核", "id": "4c492101-5152-58b3-a6bf-012f23b74c0c"}, {"title": "新五代史·卷五十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b9977b40cd7afc61ddc81473948ffdd463d53ee9/content/books/zizhi-tongjian/vol-288/year-0948/part-03/sources/library/xinwudaishi-052-zonglun-tiger-omen/source.txt", "note": "《新五代史》卷五十二，段落 xin-wudaishi-b08f244b9241-p002045；EPUB电子本，纸本及异文待核", "id": "7d0c0acb-4880-589c-8b95-bd24be5039d8"}, {"title": "资治通鉴·后汉纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ba6eb38778a9dc93b1118241befc00658469f072/content/books/zizhi-tongjian/vol-288/year-0948/part-01/sources/library/tongjian-288-948-march/source.txt", "note": "《资治通鉴》后汉纪三，段落 zizhi-tongjian-a63549944a71-p003415；电子底本待考，分段待核", "id": "3e2d1144-929c-5695-baef-ad43337f9477"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/53735e0f01570085514ad3900423782c4965fd11/content/books/zizhi-tongjian/vol-288/year-0948/part-02/sources/library/jiuwudaishi-101-march-close-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002453；EPUB电子本，纸本及异文待核", "id": "1ca67e72-a36a-5c37-b0f3-eb50ae101bf6"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/53735e0f01570085514ad3900423782c4965fd11/content/books/zizhi-tongjian/vol-288/year-0948/part-02/sources/library/jiuwudaishi-101-april-dingzhou-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002454；EPUB电子本，纸本及异文待核", "id": "00e8a9b2-6342-5a03-a9f0-100178652976"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "李涛（后晋宋初官员）", "aliases": ["李濤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李澣的兄长，后晋至宋初官员。《宋史》记他宋初任兵部尚书，去世时六十四岁，年代与887年已在杨行密军中的同名李涛不相容，本批单独建档。生卒年不凭年龄反推，后续旧库记录需逐条核对。", "biography": null, "status": "draft", "id": "c03574d2-e4e9-5739-be38-c52f0c0de233"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "赵修己", "aliases": ["趙修己"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "浚仪人，擅长术数。李守贞镇滑州时任司户参军，随后随李守贞移镇。948年叛乱前多次劝其不要轻动，未获采纳，称病回乡。生卒年未载，未将后周同名司天官的经历无证并入。", "biography": null, "status": "draft", "id": "466921a0-4aca-54da-a351-22bfaf8a12b0"}, {"name": "总伦", "aliases": ["總倫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞门下僧人，以方术预言李守贞将成为皇帝，受到其相信。《新五代史》也记总伦以方术影响李守贞，预言均按说话者的主张记录。生卒年未载。", "biography": null, "status": "draft", "id": "079788d1-e6b4-52de-b2df-58b27472ca5f"}, {"name": "赵思绾", "aliases": ["趙思綰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州人，原在赵在礼军中，后来成为赵匡赞牙将。948年王景崇试图令赵匡赞牙兵刺面防逃时，主动提出先刺自己以率众。齐藏珍建议将其杀死，王景崇不听。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b571162d-9596-5439-a443-f33cd87ea628"}, {"name": "王继勋（李守贞将）", "aliases": ["王继勋（平陆将领）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "平陆人，李守贞部将。948年李守贞自称秦王后，派他率兵占据潼关。与闽国王氏宗族成员和宋代同名人物分开，未作无证合并。生卒年未载。", "biography": null, "status": "draft", "id": "cebf1403-38a6-5f4e-b202-577b1ed71892"}, {"name": "张彦威", "aliases": ["張彥威"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "潞城人，947年二月任河东行军司马，与其他将吏多次上书劝刘知远称帝。生卒年未载。", "biography": null, "status": "draft", "id": "e0b16d41-9e50-528a-93cd-861c7eed8115"}, {"name": "罗金山", "aliases": ["羅金山"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，948年任滑州马军都指挥使，奉诏率本部兵驻守同州，使同州未被李守贞起兵吞并。生卒年未载。", "biography": null, "status": "draft", "id": "eda10654-c4ea-5bee-bf93-4594293d2d23"}, {"name": "李彝殷", "aliases": ["李彜殷", "李彝兴", "李彝興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彝殷，行军司马、权知军州事者。", "biography": null, "status": "draft", "id": "22edc111-ae26-5bce-a26b-3ae072425377"}, {"name": "李仁裕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》引948年李彝殷奏文，称李仁裕原任绥州刺史，此前被羌族首领杀害。该首领姓名有疑字，奏文所述相对时间未换算具体死亡年，相关信息尚待其他史料补核。", "biography": null, "status": "draft", "id": "96306580-28d6-582e-97e3-6f7ef6b6c902"}, {"name": "王玉（陕州都监）", "aliases": ["王玉（后汉陕州都监）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "948年任陕州都监，《旧五代史》称陕州兵马监押。四月辛巳向朝廷奏报收复潼关，实际作战日和是否本人指挥未具明文。与其他年代同名王玉分开，生卒年未载。", "biography": null, "status": "draft", "id": "f1d6d4cd-7548-5982-9e8c-1700e922f52f"}, {"name": "王章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州南乐人，曾任孔目官，随刘知远到太原。947年任权三司使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "154bd412-f052-5459-9c17-951cfcd91759"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

