ion": "三司使王章加同平章事。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8db660f2-d2c9-50cf-81ae-bcac40716954"}, {"title": "刘承祐把任官和奏事交杨邠裁决，政务开始迟滞", "start_year": 948, "end_year": 948, "time_original": "948年四月任宰相后持续形成，具体日未载", "dynasty": "五代十国", "description": "刘承祐将中书任官和各司奏事交杨邠斟酌。此后政事多由杨邠裁决，其他宰相受到限制，未获其决定的事项无人敢执行，导致政务迟滞。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "aa2f6520-e7b5-509b-bf3f-d4ddf8b225f0"}, {"title": "杨邠限制任官，强调仓储兵力，轻视文章礼乐", "start_year": null, "end_year": null, "time_original": "杨邠任相后制度实践及汉兴至亡的回顾，具体持续年月未逐项载明", "dynasty": "五代十国", "description": "杨邠要求任官符合自己的意见，认为仓储和兵力比文章礼乐更紧要，反对苏逢吉、苏禹珪任官过多，因此难以任用士人。史书回顾称有些人从后汉建立到灭亡都未获任命。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0ac01f2a-084a-5209-afa3-ee05734788a9"}, {"title": "杨邠停止门荫及百司入仕渠道", "start_year": null, "end_year": null, "time_original": "杨邠任相之后，具体实施年月未载", "dynasty": "五代十国", "description": "杨邠停止门荫及百司入仕渠道。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "91c25b10-50f7-5e7a-a1dc-391c07355b15"}, {"title": "史书记杨邠任官弊病及当时人对两苏的责备", "start_year": null, "end_year": null, "time_original": "史家对后汉任官制度的总结及所记时人评论，非单日事件", "dynasty": "五代十国", "description": "史书记杨邠任官弊病及当时人对两苏的责备。", "phases": [], "location_name": "史家评论", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "s